1	// Package incidents holds the incident-handling register: incidents are
2	// created once, evolve through append-only actions under optimistic
3	// concurrency, and link back to events without modifying them.
4	package incidents
5	
6	import (
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"sync"
12		"time"
13	)
14	
15	// Incident statuses.
16	const (
17		StatusOpen     = "open"
18		StatusResolved = "resolved"
19	)
20	
21	// Actions accepted by POST /incidents/{id}/actions. ActionCreate marks the
22	// creation entry in an incident's history.
23	const (
24		ActionCreate    = "create"
25		ActionNote      = "add_note"
26		ActionLinkEvent = "link_event"
27		ActionResolve   = "resolve"
28		ActionReopen    = "reopen"
29	)
30	
31	// ValidationError reports missing fields, wrong types, or unknown actions.
32	type ValidationError struct{ Reason string }
33	
34	func (e *ValidationError) Error() string { return e.Reason }
35	
36	// NotFoundError reports a missing incident or a missing linked event.
37	type NotFoundError struct{ Reason string }
38	
39	func (e *NotFoundError) Error() string { return e.Reason }
40	
41	// ConflictError carries the current incident version alongside the reason,
42	// so a stale-version response can report it. CurrentVersion is zero when the
43	// conflict is not version-related.
44	type ConflictError struct {
45		Reason         string
46		CurrentVersion int
47	}
48	
49	func (e *ConflictError) Error() string { return e.Reason }
50	
51	// IsValidationError reports whether err is an incident validation failure.
52	func IsValidationError(err error) bool {
53		var target *ValidationError
54		return errors.As(err, &target)
55	}
56	
57	// IsNotFoundError reports whether err is a missing-incident/event failure.
58	func IsNotFoundError(err error) bool {
59		var target *NotFoundError
60		return errors.As(err, &target)
61	}
62	
63	// IsConflictError reports whether err is an incident conflict failure.
64	func IsConflictError(err error) bool {
65		var target *ConflictError
66		return errors.As(err, &target)
67	}
68	
69	// CurrentVersionOf returns the version reported with a version conflict, or
70	// zero when err is not a version conflict.
71	func CurrentVersionOf(err error) int {
72		var target *ConflictError
73		if errors.As(err, &target) {
74			return target.CurrentVersion
75		}
76		return 0
77	}
78	
79	func validationErr(format string, args ...any) error {
80		return &ValidationError{Reason: fmt.Sprintf(format, args...)}
81	}
82	
83	func notFoundErr(format string, args ...any) error {
84		return &NotFoundError{Reason: fmt.Sprintf(format, args...)}
85	}
86	
87	func conflictErr(currentVersion int, format string, args ...any) error {
88		return &ConflictError{Reason: fmt.Sprintf(format, args...), CurrentVersion: currentVersion}
89	}
90	
91	// Creation is the normalized content of POST /incidents. Strings are trimmed
92	// of surrounding whitespace but keep their interior case.
93	type Creation struct {
94		ID       string
95		Title    string
96		Service  string
97		Operator string
98	}
99	
100	// Request is the normalized content of POST /incidents/{id}/actions. Content
101	// carries the action payload: the note text, the linked event id, or the
102	// resolve/reopen reason.
103	type Request struct {
104		IncidentID      string
105		ActionID        string
106		Operator        string
107		ExpectedVersion int
108		Type            string
109		Content         string
110	}
111	
112	// CreateResult is the result of a successful create, including an idempotent
113	// replay.
114	type CreateResult struct {
115		ID      string
116		Status  string
117		Version int
118	}
119	
120	// ActionResult is the result of a successful action, including an idempotent
121	// replay.
122	type ActionResult struct {
123		IncidentID string
124		ActionID   string
125		Version    int
126	}
127	
128	// Entry is one committed item in an incident's history: the creation itself
129	// or a later action.
130	type Entry struct {
131		ActionID string
132		Operator string
133		Action   string
134		Content  string
135		Version  int
136		At       time.Time
137	}
138	
139	// Incident is one committed snapshot, suitable for a single-version read.
140	type Incident struct {
141		ID      string
142		Title   string
143		Service string
144		Status  string
145		Version int
146		Links   []string
147		History []Entry
148	}
149	
150	// EventLookup resolves an event id without exposing the whole timeline, so
151	// incident handling never modifies events.
152	type EventLookup interface {
153		// LookupEvent returns (service, true) for a stored event, or ("", false).
154		LookupEvent(id string) (service string, ok bool)
155	}
156	
157	// BeforeCommit persists one new record while the registry lock is held and
158	// before the in-memory state advances. Returning an error rejects the request
159	// without touching the incident.
160	type BeforeCommit func(record Record) error
161	
162	// Registry is the concurrency-safe set of incidents.
163	type Registry struct {
164		mu        sync.Mutex
165		incidents map[string]*incidentState
166	
167		events       EventLookup
168		beforeCommit BeforeCommit
169		now          func() time.Time
170	}
171	
172	// incidentState is the mutable state of one incident.
173	type incidentState struct {
174		id      string
175		title   string
176		service string
177		status  string
178		version int
179	
180		links   []string
181		linkSet map[string]struct{}
182	
183		history []Entry
184		// actions remembers each successful action's normalized request and the
185		// version reached afterwards, so an identical retry replays the first
186		// result even once the version has moved on.
187		actions map[string]committedAction
188	
189		creation Creation
190	}
191	
192	type committedAction struct {
193		request       Request
194		resultVersion int
195	}
196	
197	// Option configures a Registry at construction.
198	type Option func(*Registry)
199	
200	// WithClock overrides the server clock, mainly for tests.
201	func WithClock(now func() time.Time) Option {
202		return func(r *Registry) {
203			if now != nil {
204				r.now = now
205			}
206		}
207	}
208	
209	// NewRegistry returns an empty registry. events resolves linked event ids and
210	// beforeCommit durably stores each accepted record.
211	func NewRegistry(events EventLookup, beforeCommit BeforeCommit, opts ...Option) *Registry {
212		r := &Registry{
213			incidents:    make(map[string]*incidentState),
214			events:       events,
215			beforeCommit: beforeCommit,
216			now:          func() time.Time { return time.Now().UTC() },
217		}
218		for _, opt := range opts {
219			opt(r)
220		}
221		return r
222	}
223	
224	// NormalizeCreation trims the four creation fields, keeping their interior
225	// case, and requires each to be non-empty afterwards.
226	func NormalizeCreation(input Creation) (Creation, error) {
227		var err error
228		if input.ID, err = trimRequired("id", input.ID); err != nil {
229			return Creation{}, err
230		}
231		if input.Title, err = trimRequired("title", input.Title); err != nil {
232			return Creation{}, err
233		}
234		if input.Service, err = trimRequired("service", input.Service); err != nil {
235			return Creation{}, err
236		}
237		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
238			return Creation{}, err
239		}
240		return input, nil
241	}
242	
243	// NormalizeRequest trims and validates one action request. incidentID comes
244	// from the URL path and is only checked for emptiness.
245	func NormalizeRequest(input Request) (Request, error) {
246		var err error
247		if input.IncidentID, err = trimRequired("incident id", input.IncidentID); err != nil {
248			return Request{}, err
249		}
250		if input.ActionID, err = trimRequired("action_id", input.ActionID); err != nil {
251			return Request{}, err
252		}
253		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
254			return Request{}, err
255		}
256		if input.ExpectedVersion <= 0 {
257			return Request{}, validationErr("expected_version must be a positive integer")
258		}
259		switch input.Type {
260		case ActionNote, ActionLinkEvent, ActionResolve, ActionReopen:
261		default:
262			return Request{}, validationErr("unknown action %q", input.Type)
263		}
264		if input.Content, err = trimRequired(actionContentField(input.Type), input.Content); err != nil {
265			return Request{}, err
266		}
267		return input, nil
268	}
269	
270	// actionContentField names the request member that carries each action's
271	// payload, used in validation messages.
272	func actionContentField(action string) string {
273		switch action {
274		case ActionLinkEvent:
275			return "event_id"
276		case ActionResolve, ActionReopen:
277			return "reason"
278		default:
279			return "content"
280		}
281	}
282	
283	func trimRequired(field, value string) (string, error) {
284		value = strings.TrimSpace(value)
285		if value == "" {
286			return "", validationErr("%s must not be empty", field)
287		}
288		return value, nil
289	}
290	
291	// Create accepts a new incident or replays an identical creation. A stored id
292	// presented with different normalized content conflicts.
293	func (r *Registry) Create(input Creation) (CreateResult, error) {
294		creation, err := NormalizeCreation(input)
295		if err != nil {
296			return CreateResult{}, err
297		}
298	
299		r.mu.Lock()
300		defer r.mu.Unlock()
301	
302		if existing, ok := r.incidents[creation.ID]; ok {
303			if existing.creation != creation {
304				return CreateResult{}, conflictErr(existing.version,
305					"incident %q already exists with different content", creation.ID)
306			}
307			// A creation replay returns the first result verbatim: open at
308			// version 1, even if the incident has moved on since.
309			return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
310		}
311	
312		at := r.now()
313		record := NewCreationRecord(creation, at)
314		if r.beforeCommit != nil {
315			if err := r.beforeCommit(record); err != nil {
316				return CreateResult{}, err
317			}
318		}
319		r.incidents[creation.ID] = newIncidentState(creation, at)
320		return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
321	}
322	
323	// Apply accepts one action or replays an identical one. Validation and every
324	// state check happen under the registry lock before persistence, so a
325	// rejected request leaves the incident untouched.
326	func (r *Registry) Apply(input Request) (ActionResult, error) {
327		req, err := NormalizeRequest(input)
328		if err != nil {
329			return ActionResult{}, err
330		}
331	
332		r.mu.Lock()
333		defer r.mu.Unlock()
334	
335		state, ok := r.incidents[req.IncidentID]
336		if !ok {
337			return ActionResult{}, notFoundErr("incident %q not found", req.IncidentID)
338		}
339	
340		// Idempotent replay is checked first: a retry of the first successful
341		// request still returns that result even though its expected_version is
342		// stale by now.
343		if prior, repeated := state.actions[req.ActionID]; repeated {
344			if prior.request != req {
345				return ActionResult{}, conflictErr(state.version,
346					"action %q already exists with different content", req.ActionID)
347			}
348			return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: prior.resultVersion}, nil
349		}
350	
351		if err := r.checkAction(state, req); err != nil {
352			return ActionResult{}, err
353		}
354	
355		at := r.now()
356		if r.beforeCommit != nil {
357			if err := r.beforeCommit(NewActionRecord(req, at)); err != nil {
358				return ActionResult{}, err
359			}
360		}
361		version := state.commit(req, at)
362		return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: version}, nil
363	}
364	
365	// checkAction enforces optimistic versioning, the open/resolved state
366	// machine, and the link rules. It runs with the registry lock held.
367	func (r *Registry) checkAction(state *incidentState, req Request) error {
368		if req.ExpectedVersion != state.version {
369			return conflictErr(state.version,
370				"expected version %d but incident %q is at version %d",
371				req.ExpectedVersion, state.id, state.version)
372		}
373		switch req.Type {
374		case ActionNote:
375			if state.status != StatusOpen {
376				return conflictErr(state.version, "cannot add a note to a %s incident", state.status)
377			}
378		case ActionLinkEvent:
379			if state.status != StatusOpen {
380				return conflictErr(state.version, "cannot link an event to a %s incident", state.status)
381			}
382			if r.events == nil {
383				return notFoundErr("event %q not found", req.Content)
384			}
385			service, found := r.events.LookupEvent(req.Content)
386			if !found {
387				return notFoundErr("event %q not found", req.Content)
388			}
389			if service != state.service {
390				return conflictErr(state.version,
391					"event %q belongs to service %q, not %q", req.Content, service, state.service)
392			}
393			if _, linked := state.linkSet[req.Content]; linked {
394				return conflictErr(state.version,
395					"event %q is already linked to incident %q", req.Content, state.id)
396			}
397		case ActionResolve:
398			if state.status != StatusOpen {
399				return conflictErr(state.version, "incident %q is already resolved", state.id)
400			}
401		case ActionReopen:
402			if state.status != StatusResolved {
403				return conflictErr(state.version, "incident %q is not resolved", state.id)
404			}
405		}
406		return nil
407	}
408	
409	// Get returns a point-in-time copy of one incident. The copy's status,
410	// links, version, and history all belong to the same committed version.
411	func (r *Registry) Get(id string) (Incident, error) {
412		r.mu.Lock()
413		defer r.mu.Unlock()
414		state, ok := r.incidents[id]
415		if !ok {
416			return Incident{}, notFoundErr("incident %q not found", id)
417		}
418		return state.snapshot(), nil
419	}
420	
421	func newIncidentState(creation Creation, at time.Time) *incidentState {
422		return &incidentState{
423			id:       creation.ID,
424			title:    creation.Title,
425			service:  creation.Service,
426			status:   StatusOpen,
427			version:  1,
428			links:    []string{},
429			linkSet:  make(map[string]struct{}),
430			actions:  make(map[string]committedAction),
431			history:  []Entry{{Operator: creation.Operator, Action: ActionCreate, Content: creation.Title, Version: 1, At: at}},
432			creation: creation,
433		}
434	}
435	
436	// commit advances the state by one already-validated action and returns the
437	// new version.
438	func (s *incidentState) commit(req Request, at time.Time) int {
439		switch req.Type {
440		case ActionLinkEvent:
441			s.linkSet[req.Content] = struct{}{}
442			s.links = append(s.links, req.Content)
443		case ActionResolve:
444			s.status = StatusResolved
445		case ActionReopen:
446			s.status = StatusOpen
447		}
448		s.version++
449		s.history = append(s.history, Entry{
450			ActionID: req.ActionID,
451			Operator: req.Operator,
452			Action:   req.Type,
453			Content:  req.Content,
454			Version:  s.version,
455			At:       at,
456		})
457		s.actions[req.ActionID] = committedAction{request: req, resultVersion: s.version}
458		return s.version
459	}
460	
461	func (s *incidentState) snapshot() Incident {
462		links := slices.Clone(s.links)
463		history := make([]Entry, len(s.history))
464		copy(history, s.history)
465		return Incident{
466			ID:      s.id,
467			Title:   s.title,
468			Service: s.service,
469			Status:  s.status,
470			Version: s.version,
471			Links:   links,
472			History: history,
473		}
474	}
