63				return validationErr("link action %q on %s incident in log", req.ActionID, state.status)
64			}
65			if _, linked := state.linkSet[req.Content]; linked {
66				return validationErr("event %q linked twice in incident %q log", req.Content, state.id)
67			}
68			if r.events == nil {
69				return validationErr("event %q missing while replaying incident log", req.Content)
70			}
71			service, found := r.events.LookupEvent(req.Content)
72			if !found {
73				return validationErr("linked event %q no longer exists in the event log", req.Content)
74			}
75			if service != state.service {
76				return validationErr("linked event %q service %q does not match incident %q service %q",
77					req.Content, service, state.id, state.service)
78			}
79		case ActionResolve:
80			if state.status != StatusOpen {
81				return validationErr("resolve action %q on non-open incident in log", req.ActionID)
82			}
83		case ActionReopen:
84			if state.status != StatusResolved {
85				return validationErr("reopen action %q on non-resolved incident in log", req.ActionID)
86			}
87		default:
88			return validationErr("unknown action %q in log", req.Type)
89		}
90		return nil
