1	// Package httpapi exposes the event timeline over HTTP.
2	package httpapi
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"errors"
8		"io"
9		"net/http"
10		"time"
11	
12		"github.com/cocosolocoder/signalroom/internal/events"
13		"github.com/cocosolocoder/signalroom/internal/incidents"
14	)
15	
16	// maxBodyBytes bounds a single POST request body.
17	const maxBodyBytes = 16 << 20
18	
19	// Storage durably persists a batch before it becomes visible.
20	type Storage interface {
21		Append(batch []events.Event) error
22		Poisoned() bool
23	}
24	
25	type envelope struct {
26		Events json.RawMessage `json:"events"`
27	}
28	
29	// Handler wires the timeline, its durable log, and the cursor store to HTTP
30	// routes.
31	type Handler struct {
32		timeline *events.Timeline
33		log      Storage
34		cursors  CursorStore
35	
36		incidents    *incidents.Registry
37		incidentLogs IncidentStorage
38	
39		mux *http.ServeMux
40	}
41	
42	// Option customizes a Handler at construction.
43	type Option func(*Handler)
44	
45	// WithIncidents enables the incident endpoints, backed by reg and its
46	// durable store.
47	func WithIncidents(reg *incidents.Registry, store IncidentStorage) Option {
48		return func(h *Handler) {
49			h.incidents = reg
50			h.incidentLogs = store
51		}
52	}
53	
54	// NewHandler builds the HTTP handler for a timeline backed by log. cursors
55	// supplies the per-directory signing key and snapshot storage for paging.
56	func NewHandler(timeline *events.Timeline, log Storage, cursors CursorStore, opts ...Option) *Handler {
57		h := &Handler{timeline: timeline, log: log, cursors: cursors, mux: http.NewServeMux()}
58		for _, opt := range opts {
59			opt(h)
60		}
61		h.mux.HandleFunc("/events", h.events)
62		h.mux.HandleFunc("/alerts/preview", h.previewAlerts)
63		h.mux.HandleFunc("/events/compare", h.compareEvents)
