52		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
53			// Drop exactly one incomplete trailing frame; the only mutation
54			// recovery performs, fsynced before serving.
55			if err := file.Truncate(validLen); err != nil {
56				file.Close()
57				return nil, nil, fmt.Errorf("truncate incomplete trailing incident frame: %w", err)
58			}
59			if err := file.Sync(); err != nil {
60				file.Close()
61				return nil, nil, fmt.Errorf("sync incident log: %w", err)
62			}
63			if err := syncDir(dir); err != nil {
64				file.Close()
65				return nil, nil, fmt.Errorf("sync data directory: %w", err)
66			}
