72	// replayIncidents scans the log and returns the valid records, the byte
73	// offset at which the log is known good, and an error for any corruption
74	// before that offset.
75	func replayIncidents(file *os.File) ([]incidents.Record, int64, error) {
76		data, err := os.ReadFile(file.Name())
77		if err != nil {
78			return nil, 0, fmt.Errorf("read incident log: %w", err)
79		}
80	
81		var records []incidents.Record
82		pos := int64(0)
83		for pos < int64(len(data)) {
84			remaining := int64(len(data)) - pos
85			if remaining < headerSize {
86				break // torn partial header
87			}
88			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
89			if payloadLen <= 0 || payloadLen > maxPayload {
90				return nil, 0, corruption("corrupt incident frame header at offset %d", pos)
91			}
92			frameEnd := pos + headerSize + payloadLen
93			if frameEnd > int64(len(data)) {
94				break // header landed but its payload did not: torn tail
95			}
96			payload := data[pos+headerSize : frameEnd]
97			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
98			if crc32.ChecksumIEEE(payload) != wantCRC {
99				return nil, 0, corruption("incident checksum mismatch at offset %d", pos)
100			}
101			record, err := incidents.DecodeRecord(payload)
102			if err != nil {
103				return nil, 0, corruption("illegal incident frame payload at offset %d: %v", pos, err)
104			}
