112	// before the call returns. Any write or sync failure poisons the log so that
113	// this call and every later one fail until restart.
114	func (l *IncidentLog) AppendRecord(record incidents.Record) (err error) {
115		payload, err := incidents.MarshalRecord(record)
116		if err != nil {
117			return fmt.Errorf("encode incident record: %w", err)
118		}
119		if len(payload) > maxPayload {
120			return fmt.Errorf("incident record exceeds %d byte frame limit", maxPayload)
121		}
122	
123		frame := make([]byte, headerSize+len(payload))
124		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
125		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
126		copy(frame[headerSize:], payload)
127	
128		l.mu.Lock()
129		defer l.mu.Unlock()
130		if l.poisoned {
131			return ErrPoisoned
132		}
133		defer func() {
134			if err != nil {
135				l.poisoned = true
136			}
137		}()
138	
139		if _, err = l.file.Write(frame); err != nil {
140			return fmt.Errorf("write incident log: %w", err)
141		}
142		if err = l.file.Sync(); err != nil {
143			return fmt.Errorf("sync incident log: %w", err)
144		}
145		return nil
146	}
