155	// Close releases the incident log file. The shared directory lock is owned by
156	// the event log's Log and released there.
157	func (l *IncidentLog) Close() error {
158		l.mu.Lock()
159		defer l.mu.Unlock()
160		return l.file.Close()
161	}
