21	// fakeCommit counts durable writes and can be made to fail.
22	type fakeCommit struct {
23		mu       sync.Mutex
24		records  []Record
25		failOnce bool
26		failed   bool
27	}
28	
29	func (c *fakeCommit) commit(record Record) error {
30		c.mu.Lock()
31		defer c.mu.Unlock()
32		if c.failOnce && !c.failed {
33			c.failed = true
34			return errors.New("disk full")
35		}
36		c.records = append(c.records, record)
37		return nil
38	}
39	
40	func (c *fakeCommit) count() int {
41		c.mu.Lock()
42		defer c.mu.Unlock()
43		return len(c.records)
