46	func newTestRegistry(events EventLookup) (*Registry, *fakeCommit, *tickingClock) {
47		commit := &fakeCommit{}
48		clock := newTickingClock()
49		reg := NewRegistry(events, commit.commit, WithClock(clock.now))
50		return reg, commit, clock
51	}
52	
53	// tickingClock hands out strictly increasing instants even when the wall
54	// clock would not, which also models monotonic wall time across commits.
55	type tickingClock struct {
56		mu sync.Mutex
57		t  time.Time
58	}
59	
60	func newTickingClock() *tickingClock {
61		return &tickingClock{t: time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)}
62	}
63	
64	func (c *tickingClock) now() time.Time {
65		c.mu.Lock()
66		defer c.mu.Unlock()
67		c.t = c.t.Add(time.Nanosecond)
68		return c.t
69	}
