88		}
89		if body != "" {
90			req.Header.Set("Content-Type", "application/json")
91		}
92		resp, err := http.DefaultClient.Do(req)
93		if err != nil {
94			t.Fatal(err)
95		}
96		defer resp.Body.Close()
97		raw, err := io.ReadAll(resp.Body)
98		if err != nil {
99			t.Fatal(err)
100		}
101		var out map[string]any
102		if len(bytes.TrimSpace(raw)) > 0 {
103			if err := json.Unmarshal(raw, &out); err != nil {
104				t.Fatalf("decode %q: %v", raw, err)
105			}
106		}
107		return resp.StatusCode, out
108	}
